  # Helper for structured writing of values into a RustBuffer.
  class RustBufferBuilder
    def initialize
      @rust_buf = RustBuffer.alloc 16
      @rust_buf.len = 0
    end

    def finalize
      rbuf = @rust_buf

      @rust_buf = nil

      rbuf
    end

    def discard
      return if @rust_buf.nil?

      rbuf = finalize
      rbuf.free
    end

    def write(value)
      reserve(value.bytes.size) do
        @rust_buf.data.put_array_of_char @rust_buf.len, value.bytes
      end
    end

    def write_U32(v)
      v = Meerkly.uniffi_in_range(v, 'u32', 0, 2**32)
      pack_into(4, 'L>', v)
    end

    def write_Bool(v)
      pack_into(1, 'c', v ? 1 : 0)
    end

    def write_String(v)
      v = Meerkly.uniffi_utf8(v)
      pack_into 4, 'l>', v.bytes.size
      write v
    end

    def write_Bytes(v)
      v = Meerkly.uniffi_bytes(v)
      pack_into 4, 'l>', v.bytes.size
      write v
    end

    # The Object type ProxyClient.

    def write_TypeProxyClient(obj)
      pointer = ProxyClient.uniffi_lower obj
      pack_into(8, 'Q>', pointer.address)
    end

    # The Record type ProxyConfig.

    def write_TypeProxyConfig(v)
      write_String(v.publisher_id)
      write_Sequencestring(v.gateway_addresses)
      write_Optionalstring(v.ca_cert_path)
      write_Optionalbytes(v.ca_cert_pem)
      write_Optionalu32(v.start_timeout_ms)
      write_Optionalu32(v.connect_timeout_ms)
      write_Optionalstring(v.device_id)
      write_Optionalstring(v.device_name)
      write_Optionalstring(v.sdk)
      write_Optionalstring(v.app)
      write_Optionalstring(v.network)
    end

    # The Enum type ClientState.

    def write_TypeClientState(v)
      pack_into(4, 'l>', v)
    end

    # The Optional<T> type for u32.

    def write_Optionalu32(v)
      if v.nil?
        pack_into(1, 'c', 0)
      else
        pack_into(1, 'c', 1)
        write_U32(v)
      end
    end

    # The Optional<T> type for string.

    def write_Optionalstring(v)
      if v.nil?
        pack_into(1, 'c', 0)
      else
        pack_into(1, 'c', 1)
        write_String(v)
      end
    end

    # The Optional<T> type for bytes.

    def write_Optionalbytes(v)
      if v.nil?
        pack_into(1, 'c', 0)
      else
        pack_into(1, 'c', 1)
        write_Bytes(v)
      end
    end

    # The Sequence<T> type for string.

    def write_Sequencestring(items)
      pack_into(4, 'l>', items.size)

      items.each do |item|
        write_String(item)
      end
    end

    private

    def reserve(num_bytes)
      @rust_buf = RustBuffer.reserve(@rust_buf, num_bytes) if @rust_buf.len + num_bytes > @rust_buf.capacity

      yield

      @rust_buf.len += num_bytes
    end

    def pack_into(size, format, value)
      reserve(size) do
        @rust_buf.data.put_array_of_char @rust_buf.len, [value].pack(format).bytes
      end
    end
  end

