  # Public interface members begin here.

  class ClientState
    IDLE = 1
    CONNECTING = 2
    CONNECTED = 3
    STOPPED = 4
  end

  # Record type ProxyConfig
  class ProxyConfig
    attr_reader :publisher_id, :gateway_addresses, :ca_cert_path, :ca_cert_pem, :start_timeout_ms, :connect_timeout_ms,
                :device_id, :device_name, :sdk, :app, :network

    def initialize(publisher_id:, gateway_addresses:, ca_cert_path: nil, ca_cert_pem: nil, start_timeout_ms: nil,
                   connect_timeout_ms: nil, device_id: nil, device_name: nil, sdk: nil, app: nil, network: nil)
      @publisher_id = publisher_id
      @gateway_addresses = gateway_addresses
      @ca_cert_path = ca_cert_path
      @ca_cert_pem = ca_cert_pem
      @start_timeout_ms = start_timeout_ms
      @connect_timeout_ms = connect_timeout_ms
      @device_id = device_id
      @device_name = device_name
      @sdk = sdk
      @app = app
      @network = network
    end

    def ==(other)
      return false if @publisher_id != other.publisher_id
      return false if @gateway_addresses != other.gateway_addresses
      return false if @ca_cert_path != other.ca_cert_path
      return false if @ca_cert_pem != other.ca_cert_pem
      return false if @start_timeout_ms != other.start_timeout_ms
      return false if @connect_timeout_ms != other.connect_timeout_ms
      return false if @device_id != other.device_id
      return false if @device_name != other.device_name
      return false if @sdk != other.sdk
      return false if @app != other.app
      return false if @network != other.network

      true
    end
  end

  class ProxyClient
    # A private helper for initializing instances of the class from a raw pointer,
    # bypassing any initialization logic and ensuring they are GC'd properly.
    def self.uniffi_allocate(pointer)
      pointer.autorelease = false
      inst = allocate
      inst.instance_variable_set :@pointer, pointer
      ObjectSpace.define_finalizer(inst, uniffi_define_finalizer_by_pointer(pointer, inst.object_id))
      inst
    end

    # A private helper for registering an object finalizer.
    # N.B. it's important that this does not capture a reference
    # to the actual instance, only its underlying pointer.
    def self.uniffi_define_finalizer_by_pointer(pointer, _object_id)
      proc do |_id|
        Meerkly.rust_call(
          :uniffi_meerkly_fn_free_proxyclient,
          pointer
        )
      end
    end

    # A private helper for lowering instances into a raw pointer.
    # This does an explicit typecheck, because accidentally lowering a different type of
    # object in a place where this type is expected, could lead to memory unsafety.
    def self.uniffi_check_lower(inst)
      return if inst.is_a? self

      raise TypeError, "Expected a ProxyClient instance, got #{inst}"
    end

    def uniffi_clone_pointer
      Meerkly.rust_call(
        :uniffi_meerkly_fn_clone_proxyclient,
        @pointer
      )
    end

    def self.uniffi_lower(inst)
      inst.uniffi_clone_pointer
    end

    def initialize(config)
      config = config
      RustBuffer.check_lower_TypeProxyConfig(config)
      pointer = Meerkly.rust_call_with_error(ProxyError, :uniffi_meerkly_fn_constructor_proxyclient_new,
                                             RustBuffer.alloc_from_TypeProxyConfig(config))
      @pointer = pointer
      ObjectSpace.define_finalizer(self, self.class.uniffi_define_finalizer_by_pointer(pointer, object_id))
    end

    def client_key
      result = Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_client_key, uniffi_clone_pointer)
      result.consumeIntoOptionalstring
