    def connected
      result = Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_connected, uniffi_clone_pointer)
      result == 1
    end

    def gateway_id
      result = Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_gateway_id, uniffi_clone_pointer)
      result.consumeIntoOptionalstring
    end

    def last_rejection
      result = Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_last_rejection, uniffi_clone_pointer)
      result.consumeIntoOptionalstring
    end

    def network
      result = Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_network, uniffi_clone_pointer)
      result.consumeIntoOptionalstring
    end

    def set_network(network)
      network = (network ? Meerkly.uniffi_utf8(network) : nil)
      RustBuffer.check_lower_Optionalstring(network)
      Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_set_network, uniffi_clone_pointer,
                        RustBuffer.alloc_from_Optionalstring(network))
    end

    def start
      Meerkly.rust_call_with_error(ProxyError, :uniffi_meerkly_fn_method_proxyclient_start, uniffi_clone_pointer)
    end

    def start_blocking
      Meerkly.rust_call_with_error(ProxyError, :uniffi_meerkly_fn_method_proxyclient_start_blocking,
                                   uniffi_clone_pointer)
    end

    def state
      result = Meerkly.rust_call(:uniffi_meerkly_fn_method_proxyclient_state, uniffi_clone_pointer)
      result.consumeIntoTypeClientState
    end

    def stop
      Meerkly.rust_call_with_error(ProxyError, :uniffi_meerkly_fn_method_proxyclient_stop, uniffi_clone_pointer)
    end

    def stop_blocking
      Meerkly.rust_call_with_error(ProxyError, :uniffi_meerkly_fn_method_proxyclient_stop_blocking,
                                   uniffi_clone_pointer)
    end
  end
end
